function findMatchingStreams(pa: var, forAppId: var, forPid: var, forAppName: var): var {
    if (!pa || !task.isWindow) {
        return [];
    }

    var streams = [];

    // Check appid first for app using portal
    // https://docs.pipewire.org/page_portal.html
    if (task.appId) {
        streams = forAppId(task.appId);
    }

    if (!streams.length) {
        streams = forPid(model.AppPid);
        if (streams.length) {
            pa.registerPidMatch(model.AppName);
        } else {
            // We only want to fall back to appName matching if we never managed to map
            // a PID to an audio stream window. Otherwise if you have two instances of
            // an application, one playing and the other not, it will look up appName
            // for the non-playing instance and erroneously show an indicator on both.
            if (!pa.hasPidMatch(model.AppName)) {
                streams = forAppName(model.AppName);
            }
        }
    }

    return streams;
}

function updateAudioStreams(args: var): void {
    if (args) {
        // When the task just appeared (e.g. virtual desktop switch), show the audio indicator
        // right away. Only when audio streams change during the lifetime of this task, delay
        // showing that to avoid distraction.
        delayAudioStreamIndicator = !!args.delay;
    }

    var pa = pulseAudio.item;
    task.audioStreams = findMatchingStreams(
        pa,
        appId => pa.streamsForAppId(appId),
        pid => pa.streamsForPid(pid),
        appName => pa.streamsForAppName(appName)
    );
}

function updateMicStreams(args: var): void {
    var pa = pulseAudio.item;
    task.micStreams = findMatchingStreams(
        pa,
        appId => pa.micStreamsForAppId(appId),
        pid => pa.micStreamsForPid(pid),
        appName => pa.micStreamsForAppName(appName)
    );
}

